      <main class="kb-content">
        <section class="kb-heading"><div><small>TEAM KNOWLEDGE BASE</small><h1>团队知识库</h1><p>沉淀团队经验，让每一次提问都有出处。</p></div><div class="kb-actions"><a-upload :show-upload-list="false" :before-upload="beforeUpload" accept=".txt,.pdf,.docx,.xlsx,.xls,.ppt,.pptx"><a-button type="primary">＋ 新建文档</a-button></a-upload><a-upload :show-upload-list="false" :before-upload="beforeUpload" accept=".txt,.pdf,.docx,.xlsx,.xls,.ppt,.pptx"><a-button>上传文件</a-button></a-upload></div></section>

        <section class="kb-overview kb-card"><small>知识库概览</small><div><strong>{{ knowledgeDocuments.length }}</strong><span>篇文档</span></div><div class="success"><strong>{{ readyCount }}</strong><span>篇可检索</span></div><div><strong>12</strong><span>个协作者</span></div><div><strong>3.2k</strong><span>次问答调用</span></div><button class="kb-rag" @click="useAll"><small>知识库问答</small><b>{{ conversationMode === 'rag' ? '已开启 · 全部可用文档' : '点击启用' }}</b></button></section>

        <section class="kb-section"><header><h2>最近更新</h2><button>查看全部 →</button></header><div class="kb-card kb-recent"><button v-for="doc in recentDocs" :key="doc.id" @click="selectDoc(doc.id)"><span class="file-icon" :class="fileTone(doc)">{{ fileType(doc) }}</span><span><strong>{{ doc.name }}</strong><small>{{ doc.file_type?.toUpperCase() || 'FILE' }} · {{ formatTime(doc.updated_at) }}</small></span><a-tag :color="statusColors[doc.status] || 'default'">{{ statusLabels[doc.status] || doc.status }}</a-tag></button></div></section>

