<script setup>
import { computed, ref, watch } from 'vue';

const props = defineProps({ workspaceNotice: { type: String, default: '' }, workspaceNoticeType: { type: String, default: 'info' }, knowledgeDocuments: { type: Array, default: () => [] }, uploadingDocumentNames: { type: Array, default: () => [] }, conversationMode: { type: String, default: 'chat' }, ragScopeType: { type: String, default: 'all' }, formatTime: { type: Function, required: true } });
const emit = defineEmits(['close-notice', 'upload-knowledge-document', 'delete-knowledge-document', 'add-doc-to-scope', 'update:conversation-mode', 'update:rag-scope-type', 'update:rag-document-ids']);
const selectedId = ref(null); const search = ref(''); const status = ref('all'); const sort = ref('updated');
const statusLabels = { uploaded: '已上传', parsing: '解析中', chunking: '切块中', ready: '可检索', failed: '处理失败' }; const statusColors = { uploaded: 'default', parsing: 'processing', chunking: 'gold', ready: 'success', failed: 'error' };
const statusOptions = [{ label: '全部状态', value: 'all' }, ...Object.entries(statusLabels).map(([value, label]) => ({ label, value }))]; const sortOptions = [{ label: '最近更新⌄', value: 'updated' }, { label: '名称排序', value: 'name' }];
const readyCount = computed(() => props.knowledgeDocuments.filter((doc) => doc.status === 'ready').length); const selectedDoc = computed(() => props.knowledgeDocuments.find((doc) => doc.id === selectedId.value) || null); const recentDocs = computed(() => [...props.knowledgeDocuments].sort((a, b) => Date.parse(b.updated_at || '') - Date.parse(a.updated_at || '')).slice(0, 2));
const visibleDocs = computed(() => [...props.knowledgeDocuments].filter((doc) => (!search.value || String(doc.name).toLowerCase().includes(search.value.toLowerCase())) && (status.value === 'all' || doc.status === status.value)).sort((a, b) => sort.value === 'name' ? String(a.name).localeCompare(String(b.name)) : Date.parse(b.updated_at || '') - Date.parse(a.updated_at || '')));
watch(() => props.knowledgeDocuments, (docs) => { if (docs.length && !docs.some((doc) => doc.id === selectedId.value)) selectedId.value = docs[0].id; if (!docs.length) selectedId.value = null; }, { immediate: true });
function beforeUpload(file) { emit('upload-knowledge-document', file); return false; } function selectDoc(id) { selectedId.value = id; } function fileType(doc) { return String(doc.file_type || 'file').toUpperCase().slice(0, 4); } function fileTone(doc) { return String(doc.file_type || '').toLowerCase() === 'pdf' ? 'pdf' : 'doc'; } function useAll() { emit('update:rag-document-ids', []); emit('update:rag-scope-type', 'all'); emit('update:conversation-mode', 'rag'); } function useOnly() { if (!selectedDoc.value) return; emit('update:rag-document-ids', [Number(selectedDoc.value.id)]); emit('update:rag-scope-type', 'selected'); emit('update:conversation-mode', 'rag'); }
</script>

